// Self-contained mini diff preview for Settings → Diff preferences.
//
// Why not reuse LiveDiffPane:
//   LiveDiffPane is bound to a fetched PR — it needs threadIndex,
//   draftActions, viewedState, owner/repo/SHAs, the lot. For the
//   settings preview we want zero coupling to a PR; we just want a
//   small canonical diff that re-themes the instant the user picks
//   a new option.
//
// What this component does:
//   1. Holds a baked-in before/after string pair (a couple of small
//      JS/TS functions touching highlighting, comments, and a
//      sub-line edit so all four `lineDiffStyle` modes have something
//      visible to differentiate).
//   2. Runs `buildDiffItems` against a synthetic PatchFile + FileContents
//      Map — the same path the real PR view uses, so what the user
//      sees here matches production.
//   3. Renders a stripped-down CodeView with no gutter widget, no
//      composer, no viewed checkbox. Just the diff itself.
//
// Re-renders on every usePrefs change because `shikiTheme` +
// `lineDiffStyle` flow into options, which the lib's
// `areOptionsEqual` compares shallowly.

import { useMemo, type CSSProperties } from 'react';
import { CodeView } from '@pierre/diffs/react';
import { buildDiffItems } from '../github/buildDiff';
import type { FileContents } from '../github/fetchPRFileContents';
import { DIFF_EMPHASIS_UNSAFE_CSS } from '../diff/diffEmphasisCss';
import { usePrefs } from '../util/usePrefs';

const SAMPLE_BEFORE = `// Resolve the user's display preferences with a simple cascade.
function resolvePrefs(user) {
  if (!user) return DEFAULT_PREFS;
  const stored = localStorage.getItem('pyor:prefs');
  if (stored) return JSON.parse(stored);
  return { theme: user.theme, lineDiffStyle: 'word' };
}

// Fast path for the common case (signed-in user, no overrides).
export function loadPrefs(user) {
  const start = performance.now();
  const prefs = resolvePrefs(user);
  console.log('loadPrefs', performance.now() - start, 'ms');
  return prefs;
}
`;

const SAMPLE_AFTER = `// Resolve the user's display preferences via TanStack Query so
// changes from Settings propagate live to every open Changes tab.
function resolvePrefs(user) {
  if (!user) return DEFAULT_PREFS;
  const stored = localStorage.getItem('pyor:diffPrefs');
  if (stored) return JSON.parse(stored);
  return { theme: user.theme, lineDiffStyle: 'word-alt' };
}

export function loadPrefs(user) {
  return resolvePrefs(user);
}
`;

/** Synthetic patch big enough to show additions, deletions, and
 * intra-line edits — enough surface area for every line-diff style
 * to render visibly different output. */
const SAMPLE_FILE = {
  filename: 'src/util/prefs.ts',
  status: 'modified',
  additions: 4,
  deletions: 8,
  changes: 12,
  // The buildDiff path runs through parseDiffFromFile when oldText +
  // newText are supplied; the `patch` field is ignored on that path.
  patch: null,
};

const SAMPLE_CONTENTS = new Map<string, FileContents>([
  [
    'src/util/prefs.ts',
    { oldText: SAMPLE_BEFORE, newText: SAMPLE_AFTER, isBinary: false },
  ],
]);

export function SettingsDiffPreview() {
  const { prefs } = usePrefs();

  const build = useMemo(
    () =>
      buildDiffItems([SAMPLE_FILE], SAMPLE_CONTENTS, {
        ignoreWhitespace: true,
        // Stable demo cache keys so the worker pool reuses tokenisation
        // across theme flips instead of re-tokenising the same source
        // on every dropdown change.
        headSha: 'pyor-settings-preview-head',
        baseSha: 'pyor-settings-preview-base',
      }),
    [],
  );

  const options = useMemo(
    () => ({
      stickyHeaders: false,
      enableGutterUtility: false,
      enableLineSelection: false,
      diffStyle: 'split' as const,
      layout: { paddingTop: 0, paddingBottom: 12, gap: 0 },
      ...(prefs.theme ? { theme: prefs.theme } : {}),
      ...(prefs.lineDiffStyle ? { lineDiffType: prefs.lineDiffStyle } : {}),
      // Same intra-line emphasis fix the real diff applies (see
      // diffEmphasisCss.ts) so the preview matches production.
      unsafeCSS: DIFF_EMPHASIS_UNSAFE_CSS,
    }),
    [prefs.theme, prefs.lineDiffStyle],
  );

  // Diff font sizing flows through the `--diffs-font-size` /
  // `--diffs-line-height` CSS custom properties the lib reads at the
  // host root. Inheriting via inline style on the wrapper keeps the
  // values dynamic (per ADR 0011) without touching the lib's API.
  return (
    <div
      className="relative mt-3.5 flex h-[280px] flex-col overflow-hidden rounded-lg border bg-canvas"
      style={
        {
          '--diffs-font-size': `${prefs.fontSize}px`,
          '--diffs-line-height': `${prefs.lineHeight}px`,
        } as CSSProperties
      }
    >
      <div className="flex h-[26px] flex-shrink-0 items-center border-b bg-surface px-2.5 text-[11px] text-muted-foreground">
        Preview
      </div>
      <CodeView
        items={build.items}
        options={options}
        className="min-h-0 flex-1 overflow-auto"
      />
    </div>
  );
}
